-- Paket ABT "abt-x8-sisa-tuntutan-21okt" (21 Okt 2026): sisa paket x4 - kutipan petitum untuk pemicu tuntutan lain (layar), harta bersama dalam
-- gugatan rekonvensi cerai talak. 3 variabel baru, 0 baris diubah. Blangko RTF yang ditambal: 1 (lihat rtf-daftar-tambal.tsv).
-- PERIKSA: tiap variabel baru dan tiap baris yang diubah persis isi paket; baris terakhir "SEMUA COCOK".
SELECT 'var 3450 baru' AS butir, (SELECT COUNT(*) FROM abt_variabel WHERE (no_var=3450 AND MD5(nama)='f8983d4f21ee9c0ee7dac5417ec2c8dc' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='bfd6fed2fd020c5a97ac2cd7ca1231ad' AND IFNULL(MD5(default_data),'-')='-')) AS cocok;
SELECT 'var 3451 baru' AS butir, (SELECT COUNT(*) FROM abt_variabel WHERE (no_var=3451 AND MD5(nama)='1473f7c13293c56fd49710095c586d7f' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='e68587a70636b2e1ca008b9e1b21ad2f' AND IFNULL(MD5(default_data),'-')='-')) AS cocok;
SELECT 'var 3452 baru' AS butir, (SELECT COUNT(*) FROM abt_variabel WHERE (no_var=3452 AND MD5(nama)='37e7dbe69017ebd8ff17cd7b2a513ce7' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='740623d500419c0bb58e3010149a6d18' AND IFNULL(MD5(default_data),'-')='-')) AS cocok;
SELECT IF((SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=3450 AND MD5(nama)='f8983d4f21ee9c0ee7dac5417ec2c8dc' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='bfd6fed2fd020c5a97ac2cd7ca1231ad' AND IFNULL(MD5(default_data),'-')='-') OR (no_var=3451 AND MD5(nama)='1473f7c13293c56fd49710095c586d7f' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='e68587a70636b2e1ca008b9e1b21ad2f' AND IFNULL(MD5(default_data),'-')='-') OR (no_var=3452 AND MD5(nama)='37e7dbe69017ebd8ff17cd7b2a513ce7' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='740623d500419c0bb58e3010149a6d18' AND IFNULL(MD5(default_data),'-')='-'))) = 3, 'SEMUA COCOK', 'TIDAK COCOK') AS hasil;
